namespace MCS.Framework.Controls
{
    public static class Signature
    {
        public static string RenderSignature(string signatureControlId, string hdnIdToSaveBase64Image)
        {
            StringBuilder controlStream = new StringBuilder();

            string clearButtonId = "btn" + signatureControlId;

            controlStream.Append("<div class='Signature'>");
            controlStream.AppendFormat("<button id='{0}' type='submit'><img src='data:image/png;base64,' alt='Submit'></button>", clearButtonId);
            controlStream.AppendFormat("<div id='{0}'></div>", signatureControlId);
            controlStream.Append("</div>");

            controlStream.AppendFormat("<script type='text/javascript'> Signature('{0}', '{1}', '{2}'); </script>", signatureControlId, hdnIdToSaveBase64Image, clearButtonId);

            return controlStream.ToString();
        }

        //public static string GetSignature( string hiddenFieldIdToStoreSignatureData)
        //{
        //    StringBuilder signatureData = new StringBuilder();

        //    signatureData.AppendFormat("GetSignature({0});", hiddenFieldIdToStoreSignatureData);

        //    return signatureData.ToString();
        //}

        public static string RenderSignatureResources()
        {
            string css = Styles.Render("~/MCS.Framework.Controls/StylesSignature").ToString();
            string js = Scripts.Render("~/MCS.Framework.Controls/JSSignature").ToString();

            return css + js;
        }
    }
}
